<?php
namespace App\Http\Controllers;use App\Models\{Rfq,RfqItem,RfqAttachment,ReplacementRequest,Contact,Lead,Product};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class InquiryController extends Controller {
 public function rfqForm(Request $r){$product=$r->product?Product::find($r->product):null;return view('rfq.create',compact('product'));}
 public function rfqStore(Request $r){$d=$r->validate(['full_name'=>'required|max:150','company_name'=>'nullable|max:150','email'=>'required|email','phone'=>'required|max:50','country'=>'nullable|max:100','emirate'=>'nullable|max:100','type'=>'required|in:general,product,replacement,project,technical_support','product_id'=>'nullable|exists:products,id','product_name'=>'nullable|max:255','brand_name'=>'nullable|max:255','model_series'=>'nullable|max:255','quantity'=>'nullable|integer|min:1|max:99999','required_delivery_date'=>'nullable|date','application'=>'nullable|max:3000','message'=>'nullable|max:10000','privacy_consent'=>'accepted','attachments.*'=>'nullable|file|max:20480|mimes:pdf,jpg,jpeg,png,doc,docx,xls,xlsx,dwg,zip']);
  $rfq=DB::transaction(function()use($r,$d){$rfq=Rfq::create(array_merge(collect($d)->except(['product_id','product_name','brand_name','model_series','quantity','attachments'])->all(),['rfq_number'=>$this->nextRfqNumber(),'utm_source'=>$r->utm_source,'utm_medium'=>$r->utm_medium,'utm_campaign'=>$r->utm_campaign,'utm_term'=>$r->utm_term,'utm_content'=>$r->utm_content]));RfqItem::create(['rfq_id'=>$rfq->id,'product_id'=>$r->product_id,'product_name'=>$r->product_name,'brand_name'=>$r->brand_name,'model_series'=>$r->model_series,'quantity'=>$r->quantity?:1,'requirement'=>$r->message]);foreach($r->file('attachments',[]) as $f){$path=$f->store('rfq/'.$rfq->rfq_number,'public');RfqAttachment::create(['rfq_id'=>$rfq->id,'file_path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime_type'=>$f->getMimeType(),'file_size'=>$f->getSize()]);}Lead::create(['source'=>$r->utm_source?:'website','name'=>$rfq->full_name,'company'=>$rfq->company_name,'email'=>$rfq->email,'phone'=>$rfq->phone,'reference_type'=>Rfq::class,'reference_id'=>$rfq->id,'utm_source'=>$r->utm_source,'utm_medium'=>$r->utm_medium,'utm_campaign'=>$r->utm_campaign]);return $rfq;});return redirect()->route('rfq.thankyou',['ref'=>$rfq->rfq_number]);}
 public function replacementForm(){return view('replacement.create');}
 public function replacementStore(Request $r){$d=$r->validate(['full_name'=>'required|max:150','company_name'=>'nullable|max:150','email'=>'required|email','phone'=>'required|max:50','manufacturer'=>'nullable|max:150','model'=>'nullable|max:150','power'=>'nullable|max:100','rpm'=>'nullable|max:100','voltage'=>'nullable|max:100','gear_ratio'=>'nullable|max:100','torque'=>'nullable|max:100','mounting'=>'nullable|max:100','application'=>'nullable|max:3000','message'=>'nullable|max:10000','nameplate'=>'nullable|image|max:10240']);if($r->hasFile('nameplate'))$d['nameplate_path']=$r->file('nameplate')->store('nameplates','public');$d['reference_number']='REP-'.now()->format('Y').'-'.str_pad((string)((ReplacementRequest::max('id')??0)+1),5,'0',STR_PAD_LEFT);$item=ReplacementRequest::create($d);Lead::create(['source'=>'website','name'=>$item->full_name,'company'=>$item->company_name,'email'=>$item->email,'phone'=>$item->phone,'reference_type'=>ReplacementRequest::class,'reference_id'=>$item->id]);return redirect()->route('replacement.thankyou',['ref'=>$item->reference_number]);}
 public function contact(){return view('contact.index');}
 public function contactStore(Request $r){$d=$r->validate(['name'=>'required|max:150','company'=>'nullable|max:150','email'=>'required|email','phone'=>'nullable|max:50','subject'=>'nullable|max:200','department'=>'nullable|max:100','message'=>'required|max:10000','attachment'=>'nullable|file|max:10240']);if($r->hasFile('attachment'))$d['attachment']=$r->file('attachment')->store('contact','public');Contact::create($d);return back()->with('success','Thank you. Your enquiry has been received.');}
 private function nextRfqNumber():string{return 'RFQ-'.now()->format('Y').'-'.str_pad((string)((Rfq::max('id')??0)+1),5,'0',STR_PAD_LEFT);}
}
